-- Create missing tables if they do not exist

CREATE TABLE IF NOT EXISTS public.courses (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  description text,
  course_type text,
  web_link text,
  video_link text,
  in_learning_academy boolean DEFAULT false,
  is_hidden boolean DEFAULT false,
  is_featured boolean DEFAULT false,
  display_order int,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.course_tasks (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  course_id uuid REFERENCES public.courses(id) ON DELETE CASCADE NOT NULL,
  name text NOT NULL,
  description text,
  sort_order float,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.questions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question text NOT NULL,
  category text,
  upvotes int DEFAULT 0,
  is_faq boolean DEFAULT false,
  asked_by text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.answers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  question_id uuid REFERENCES public.questions(id) ON DELETE CASCADE NOT NULL,
  answer text NOT NULL,
  answered_by text,
  upvotes int DEFAULT 0,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.questions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.answers ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='courses' AND policyname='Anyone can view courses') THEN
    CREATE POLICY "Anyone can view courses" ON public.courses FOR SELECT USING (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='course_tasks' AND policyname='Anyone can view course tasks') THEN
    CREATE POLICY "Anyone can view course tasks" ON public.course_tasks FOR SELECT USING (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='questions' AND policyname='Anyone can view questions') THEN
    CREATE POLICY "Anyone can view questions" ON public.questions FOR SELECT USING (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='questions' AND policyname='Authenticated users can ask questions') THEN
    CREATE POLICY "Authenticated users can ask questions" ON public.questions FOR INSERT TO authenticated WITH CHECK (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='answers' AND policyname='Anyone can view answers') THEN
    CREATE POLICY "Anyone can view answers" ON public.answers FOR SELECT USING (true);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='answers' AND policyname='Authenticated users can answer') THEN
    CREATE POLICY "Authenticated users can answer" ON public.answers FOR INSERT TO authenticated WITH CHECK (true);
  END IF;
END $$;

-- Create remaining tables if they don't exist
CREATE TABLE IF NOT EXISTS public.events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title text NOT NULL,
  description text,
  location text,
  address text,
  event_date timestamptz NOT NULL,
  end_date timestamptz,
  instructor text,
  is_published boolean DEFAULT true,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.resource_categories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL,
  description text,
  icon text,
  sort_order int DEFAULT 0,
  created_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.resources (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  category_id uuid,
  name text NOT NULL,
  description text,
  address text,
  city text DEFAULT 'Philadelphia',
  state text DEFAULT 'PA',
  zip_code text,
  phone text,
  email text,
  website text,
  hours text,
  latitude double precision,
  longitude double precision,
  is_published boolean DEFAULT true,
  tags text[] DEFAULT '{}',
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.saved_resources (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  resource_id uuid NOT NULL,
  created_at timestamptz DEFAULT now(),
  UNIQUE(user_id, resource_id)
);

ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename='events' AND policyname='Anyone can view published events') THEN
    CREATE POLICY "Anyone can view published events" ON public.events FOR SELECT USING (is_published = true);
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_course_tasks_course_id ON public.course_tasks(course_id);
CREATE INDEX IF NOT EXISTS idx_answers_question_id ON public.answers(question_id);
CREATE INDEX IF NOT EXISTS idx_events_is_published_date ON public.events(is_published, event_date) WHERE is_published = true;

-- Clear existing data (order matters for FK constraints)
DELETE FROM public.answers;
DELETE FROM public.questions;
DELETE FROM public.course_tasks;
DELETE FROM public.courses;
DELETE FROM public.saved_resources;
DELETE FROM public.resources;
DELETE FROM public.resource_categories;
DELETE FROM public.events;

