INSERT INTO public.courses (name, description, course_type, web_link, video_link, in_learning_academy, is_hidden, is_featured, display_order) VALUES ('Ten Reentry Steps', 'Here’s a ten-step guide tailored for individuals in Philadelphia reentering society after incarceration, focusing on securing housing, finding employment, and adjusting to life outside.', 'Basic Needs', NULL, NULL, FALSE, TRUE, FALSE, 1);

-- Course Tasks (12 rows)
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Resume', 'Get information about each job and position I had', 1, (SELECT id FROM public.courses WHERE name = 'How to Write a Great Resume' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Bank Account', 'Find a banking institution that fits my needs', 1.23, (SELECT id FROM public.courses WHERE name = 'Manage a Savings Account' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Step 10: Focus on Self-Care and Adjustment', 'Healthy Routines: Establish daily routines that include exercise, healthy eating, and mindfulness practices.
Community Involvement: Engage with your community through activities, workshops, or local events to foster a sense of belonging.', 10, (SELECT id FROM public.courses WHERE name = 'Ten Reentry Steps' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Step 9: Build a Support Network', 'Reconnect with Family and Friends: Strengthen your support system by reaching out to loved ones.
Support Groups: Join support groups for people reentering society to share experiences and coping strategies.', 9, (SELECT id FROM public.courses WHERE name = 'Ten Reentry Steps' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Step 8: Understand Your Rights', 'Know Your Legal Rights: Familiarize yourself with your rights regarding housing and employment, particularly concerning discrimination due to your criminal record.
Legal Aid Resources: Connect with organizations that provide legal assistance if you face discrimination or challenges.', 8, (SELECT id FROM public.courses WHERE name = 'Ten Reentry Steps' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Step 7: Prepare for Interviews', 'Mock Interviews: Practice interviewing with friends, family, or career coaches to build confidence.
Discuss Your Background: Be prepared to explain your incarceration in a positive light, focusing on what you learned and how you''ve changed.', 7, (SELECT id FROM public.courses WHERE name = 'Ten Reentry Steps' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Step 6: Job Search and Application', 'Resume and Cover Letter: Create a professional resume and cover letter that highlight your skills and experience.
Job Portals and Networking: Use job search websites (like Indeed or LinkedIn) and network through community organizations or job fairs.', 6, (SELECT id FROM public.courses WHERE name = 'Ten Reentry Steps' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Step 5: Develop Job Skills', 'Job Training Programs: Enroll in programs that offer skills training and workshops to enhance your employability.
Volunteer Opportunities: Gain experience and build your resume by volunteering with local nonprofits.', 5, (SELECT id FROM public.courses WHERE name = 'Ten Reentry Steps' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Step 4: Connect with Support Services', 'Reentry Programs: Seek out local organizations that offer support for formerly incarcerated individuals, such as the Philadelphia Reentry Coalition.
Mental Health Services: Consider accessing counseling or mental health services to help with the transition.', 4, (SELECT id FROM public.courses WHERE name = 'Ten Reentry Steps' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Step 3: Find Stable Housing', 'Temporary Housing: Look for shelters or transitional housing programs specifically for those reentering society.
Search for Permanent Housing: Use resources like the Philadelphia Housing Authority or local housing agencies. Check for any programs that assist individuals with criminal records.', 3, (SELECT id FROM public.courses WHERE name = 'Ten Reentry Steps' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Step 2: Secure Identification', 'Obtain Necessary IDs: Ensure you have a government-issued ID, Social Security card, and any necessary documents that can aid in employment and housing applications.
Contact Local Organizations: Organizations like the Philadelphia Office of Reentry Partnerships can help with obtaining these documents.', 2, (SELECT id FROM public.courses WHERE name = 'Ten Reentry Steps' LIMIT 1));
INSERT INTO public.course_tasks (name, description, sort_order, course_id) VALUES ('Step 1: Create a Reentry Plan', 'Assess Your Needs: Outline your immediate needs for housing, employment, and support.
Set Goals: Identify short-term and long-term goals, such as finding a job within three months or stable housing within six.', 1, (SELECT id FROM public.courses WHERE name = 'Ten Reentry Steps' LIMIT 1));

